create table if not exists atlas.source_custody_surface_families (family_key text primary key, description text not null, blocking boolean not null default true, active boolean not null default true, created_at timestamptz not null default now(), check (family_key ~ '^[a-z0-9_]+$'));
insert into atlas.source_custody_surface_families (family_key, description, blocking) values ('functions','Atlas function signatures, definitions, security mode and configuration',true),('rls_policies','Atlas row-level-security policy definitions',true),('triggers','Atlas non-internal trigger definitions',true),('constraints','Atlas table constraints',true),('rpc_privileges','Atlas authenticated/anonymous/service RPC privilege contract',true) on conflict (family_key) do update set description=excluded.description, blocking=excluded.blocking, active=true;
create table if not exists atlas.source_custody_adjudications (id uuid primary key default gen_random_uuid(), custody_key text not null, custody_class text not null check (custody_class in ('version_drift','surface_supersession','historical_provenance','other')), disposition text not null check (disposition in ('accepted','rejected','superseded')), evidence jsonb not null default '{}'::jsonb, rationale text not null, adjudicated_by text not null, adjudicated_at timestamptz not null default now(), supersedes_adjudication_id uuid references atlas.source_custody_adjudications(id), check (custody_key<>''), check (rationale<>''), check (adjudicated_by<>''));
create index if not exists source_custody_adjudications_key_time_idx on atlas.source_custody_adjudications (custody_key, adjudicated_at desc);
create or replace function atlas.block_source_custody_adjudication_mutation_v1() returns trigger language plpgsql set search_path=pg_catalog,atlas as $function$ begin raise exception 'Atlas source-custody adjudications are append-only.' using errcode='55000'; end; $function$;
drop trigger if exists source_custody_adjudications_append_only on atlas.source_custody_adjudications;
create trigger source_custody_adjudications_append_only before update or delete on atlas.source_custody_adjudications for each row execute function atlas.block_source_custody_adjudication_mutation_v1();
create or replace function atlas.source_custody_live_surface_v1() returns table (family_key text, artifact_key text, canonical_definition text, fingerprint_sha256 text) language sql stable security definer set search_path=pg_catalog,atlas as $function$
with governed as (select family_key from atlas.source_custody_surface_families where active and blocking), function_surface as (select 'functions'::text family_key, format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) artifact_key, concat_ws(E'\n','kind=function','identity='||format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'security_definer='||p.prosecdef::text,'config='||coalesce(array_to_string(p.proconfig,','),''),pg_get_functiondef(p.oid)) canonical_definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='atlas' and p.prokind in ('f','p') and p.proname not like 'source_custody_%' and p.proname<>'block_source_custody_adjudication_mutation_v1'), policy_surface as (select 'rls_policies'::text,format('%I.%I:%I',schemaname,tablename,policyname),concat_ws(E'\n','kind=policy','identity='||format('%I.%I:%I',schemaname,tablename,policyname),'permissive='||permissive,'roles='||array_to_string(roles,','),'command='||cmd,'using='||coalesce(qual,''),'check='||coalesce(with_check,'')) from pg_policies where schemaname='atlas' and tablename not like 'source_custody_%'), trigger_surface as (select 'triggers'::text,format('%I.%I:%I',n.nspname,c.relname,t.tgname),concat_ws(E'\n','kind=trigger','identity='||format('%I.%I:%I',n.nspname,c.relname,t.tgname),pg_get_triggerdef(t.oid,true)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='atlas' and not t.tgisinternal and c.relname not like 'source_custody_%'), constraint_surface as (select 'constraints'::text,format('%I.%I:%I',n.nspname,c.relname,con.conname),concat_ws(E'\n','kind=constraint','identity='||format('%I.%I:%I',n.nspname,c.relname,con.conname),'type='||con.contype::text,pg_get_constraintdef(con.oid,true)) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='atlas' and c.relname not like 'source_custody_%'), rpc_surface as (select 'rpc_privileges'::text,r.signature,concat_ws(E'\n','kind=rpc_privilege','identity='||r.signature,'classification='||r.classification,'review_status='||r.review_status,'authenticated='||r.authenticated_execute_expected::text,'anonymous='||r.anonymous_execute_expected::text,'service='||r.service_execute_expected::text,'security_definer='||r.security_definer_expected::text) from atlas.authenticated_rpc_registry r where r.review_status='active'), all_surface as (select * from function_surface union all select * from policy_surface union all select * from trigger_surface union all select * from constraint_surface union all select * from rpc_surface) select s.family_key,s.artifact_key,s.canonical_definition,encode(extensions.digest(convert_to(s.canonical_definition,'UTF8'),'sha256'),'hex') from all_surface s join governed g using(family_key) order by s.family_key,s.artifact_key;
$function$;
create or replace function atlas.source_custody_live_packet_v1() returns jsonb language sql stable security definer set search_path=pg_catalog,atlas as $function$ with rows as (select * from atlas.source_custody_live_surface_v1()), families as (select family_key,count(*) artifact_count,encode(extensions.digest(convert_to(string_agg(artifact_key||E'\t'||fingerprint_sha256,E'\n' order by artifact_key),'UTF8'),'sha256'),'hex') family_fingerprint from rows group by family_key) select jsonb_build_object('contractVersion',1,'families',coalesce((select jsonb_agg(jsonb_build_object('familyKey',family_key,'artifactCount',artifact_count,'fingerprintSha256',family_fingerprint) order by family_key) from families),'[]'::jsonb),'artifacts',coalesce((select jsonb_agg(jsonb_build_object('familyKey',family_key,'artifactKey',artifact_key,'fingerprintSha256',fingerprint_sha256) order by family_key,artifact_key) from rows),'[]'::jsonb)); $function$;
alter table atlas.source_custody_surface_families enable row level security; alter table atlas.source_custody_adjudications enable row level security; revoke all on table atlas.source_custody_surface_families from public,anon,authenticated; revoke all on table atlas.source_custody_adjudications from public,anon,authenticated; grant select on table atlas.source_custody_surface_families to service_role; grant select on table atlas.source_custody_adjudications to service_role; revoke all on function atlas.source_custody_live_surface_v1() from public,anon,authenticated; revoke all on function atlas.source_custody_live_packet_v1() from public,anon,authenticated; grant execute on function atlas.source_custody_live_surface_v1() to service_role; grant execute on function atlas.source_custody_live_packet_v1() to service_role; revoke all on function atlas.block_source_custody_adjudication_mutation_v1() from public,anon,authenticated;